/** @param {number} value */
export function quartIn(value: number) { return value ** 4; }
/** @param {number} value */
export function quartOut(value: number) { return 1 - (1 - value) ** 4; }
/** @param {number} value */
export function quartInOut(value: number) { return value < 0.5 ? 8 * value ** 4 : 1 - (-2 * value + 2) ** 4 / 2; }
/** @param {number} value */
export function quintIn(value: number) { return value ** 5; }
/** @param {number} value */
export function quintOut(value: number) { return 1 - (1 - value) ** 5; }
/** @param {number} value */
export function quintInOut(value: number) { return value < 0.5 ? 16 * value ** 5 : 1 - (-2 * value + 2) ** 5 / 2; }
/** @param {number} value */
export function circIn(value: number) { return 1 - Math.sqrt(Math.max(0, 1 - value ** 2)); }
/** @param {number} value */
export function circOut(value: number) { return Math.sqrt(Math.max(0, 1 - (value - 1) ** 2)); }
/** @param {number} value */
export function circInOut(value: number) { return value < 0.5 ? (1 - Math.sqrt(Math.max(0, 1 - (2 * value) ** 2))) / 2 : (Math.sqrt(Math.max(0, 1 - (-2 * value + 2) ** 2)) + 1) / 2; }
/** @param {number} value */
export function backIn(value: number) { return value === 0 || value === 1 ? value : 2.70158 * value ** 3 - 1.70158 * value ** 2; }
/** @param {number} value */
export function backOut(value: number) { return value === 0 || value === 1 ? value : 1 + 2.70158 * (value - 1) ** 3 + 1.70158 * (value - 1) ** 2; }
/** @param {number} value */
export function backInOut(value: number) {
  if (value === 0 || value === 1) return value;
  const c2 = 1.70158 * 1.525;
  return value < 0.5 ? (2 * value) ** 2 * ((c2 + 1) * 2 * value - c2) / 2 : ((2 * value - 2) ** 2 * ((c2 + 1) * (2 * value - 2) + c2) + 2) / 2;
}
/** @param {number} value */
export function elasticIn(value: number) { return value === 0 || value === 1 ? value : -(2 ** (10 * value - 10)) * Math.sin((10 * value - 10.75) * (2 * Math.PI / 3)); }
/** @param {number} value */
export function elasticOut(value: number) { return value === 0 || value === 1 ? value : 2 ** (-10 * value) * Math.sin((10 * value - 0.75) * (2 * Math.PI / 3)) + 1; }
/** @param {number} value */
export function elasticInOut(value: number) {
  if (value === 0 || value === 1) return value;
  const oscillation = Math.sin((20 * value - 11.125) * (2 * Math.PI / 4.5));
  return value < 0.5 ? -(2 ** (20 * value - 10) * oscillation) / 2 : (2 ** (-20 * value + 10) * oscillation) / 2 + 1;
}
/** @param {number} value */
export function bounceOut(value: number) {
  if (value === 0 || value === 1) return value;
  const n1 = 7.5625, d1 = 2.75;
  if (value < 1 / d1) return n1 * value * value;
  if (value < 2 / d1) return n1 * (value - 1.5 / d1) ** 2 + 0.75;
  if (value < 2.5 / d1) return n1 * (value - 2.25 / d1) ** 2 + 0.9375;
  return n1 * (value - 2.625 / d1) ** 2 + 0.984375;
}
/** @param {number} value */
export function bounceIn(value: number) { return value === 0 || value === 1 ? value : 1 - bounceOut(1 - value); }
/** @param {number} value */
export function bounceInOut(value: number) { return value === 0 || value === 1 ? value : value < 0.5 ? (1 - bounceOut(1 - 2 * value)) / 2 : (1 + bounceOut(2 * value - 1)) / 2; }
/** @param {number} value */
export function smoothStep(value: number) { return value * value * (3 - 2 * value); }
/** @param {number} value */
export function smootherStep(value: number) { return value ** 3 * (value * (value * 6 - 15) + 10); }

export const namedEasingFunctions = {
  linear, quadIn, quadOut, quadInOut, cubicIn, cubicOut, cubicInOut,
  quartIn, quartOut, quartInOut, quintIn, quintOut, quintInOut,
  sineIn, sineOut, sineInOut, expoIn, expoOut, expoInOut, circIn, circOut, circInOut,
  backIn, backOut, backInOut, elasticIn, elasticOut, elasticInOut,
  bounceIn, bounceOut, bounceInOut, smoothStep, smootherStep
};

export const centiEase = {
  Linear: { None: linear },
  Quadratic: { In: quadIn, Out: quadOut, InOut: quadInOut },
  Cubic: { In: cubicIn, Out: cubicOut, InOut: cubicInOut },
  Quartic: { In: quartIn, Out: quartOut, InOut: quartInOut },
  Quintic: { In: quintIn, Out: quintOut, InOut: quintInOut },
  Sinusoidal: { In: sineIn, Out: sineOut, InOut: sineInOut },
  Exponential: { In: expoIn, Out: expoOut, InOut: expoInOut },
  Circular: { In: circIn, Out: circOut, InOut: circInOut },
  Back: { In: backIn, Out: backOut, InOut: backInOut },
  Elastic: { In: elasticIn, Out: elasticOut, InOut: elasticInOut },
  Bounce: { In: bounceIn, Out: bounceOut, InOut: bounceInOut },
  Smoothstep: { InOut: smoothStep },
  Smootherstep: { InOut: smootherStep }
};

/** @param {number} value @param {number[]} bezier */
export function cubicBezier(value: number, bezier: number[]) {
  const [x1 = 0, y1 = 0, x2 = 1, y2 = 1] = bezier;
  const target = clamp01(value);
  let parameter = target;

  // Newton-Raphson converges quickly for normal CSS cubic-bezier handles.
  for (let iteration = 0; iteration < 8; iteration += 1) {
    const difference = cubic(parameter, 0, x1, x2, 1) - target;
    const slope = cubicDerivative(parameter, 0, x1, x2, 1);
    if (Math.abs(difference) < 0.00001 || Math.abs(slope) < 0.00001) break;
    parameter = clamp01(parameter - difference / slope);
  }

  // Bisection stabilizes non-linear or flat x control regions.
  let lower = 0;
  let upper = 1;
  for (let iteration = 0; iteration < 12; iteration += 1) {
    const x = cubic(parameter, 0, x1, x2, 1);
    if (Math.abs(x - target) < 0.00001) break;
    if (x < target) lower = parameter;
    else upper = parameter;
    parameter = (lower + upper) / 2;
  }

  return cubic(parameter, 0, y1, y2, 1);
}

/** @param {string | undefined} easing @param {number} value @param {number[] | undefined} bezier */
export function evaluateEasing(easing: string | undefined, value: number, bezier?: number[]) {
  const progress = clamp01(value);
  if (easing === "step") return 0;
  if (easing === "bezier") return cubicBezier(progress, bezier ?? [0.25, 0.1, 0.25, 1]);
  return namedEasingFunctions[easing as keyof typeof namedEasingFunctions]?.(progress) ?? progress;
}

/** @param {number} value @param {number} a @param {number} b @param {number} c @param {number} d */
function cubic(value: number, a: number, b: number, c: number, d: number) {
  const inverse = 1 - value;
  return inverse ** 3 * a + 3 * inverse ** 2 * value * b + 3 * inverse * value ** 2 * c + value ** 3 * d;
}

/** @param {number} value @param {number} a @param {number} b @param {number} c @param {number} d */
function cubicDerivative(value: number, a: number, b: number, c: number, d: number) {
  const inverse = 1 - value;
  return 3 * inverse ** 2 * (b - a) + 6 * inverse * value * (c - b) + 3 * value ** 2 * (d - c);
}

